    92→    totalUsers: 156,
    93→    totalPosts: 42,
    94→    totalViews: 12450,
    95→    activeUsers: 23,
    96→  });
    97→});
    98→
    99→// Get All Posts
   100→app.get('/api/admin/posts', authMiddleware, (req: Request, res: Response) => {
   101→  res.json([
   102→    {
   103→      id: 1,
   104→      title: 'FreeLang 소개',
   105→      author: '김진',
   106→      createdAt: '2026-03-01T10:00:00Z',
   107→      views: 450,
   108→    },
   109→    {
   110→      id: 2,
   111→      title: 'OAuth 2.0 구현 가이드',
   112→      author: '김진',
   113→      createdAt: '2026-03-10T14:30:00Z',
   114→      views: 320,
   115→    },
   116→  ]);
   117→});
   118→
   119→// Delete Post
   120→app.delete(
   121→  '/api/admin/posts/:id',
   122→  authMiddleware,
   123→  (req: Request, res: Response) => {
   124→    const { id } = req.params;
