     1→/**
     2→ * OAuth 2.0 Configuration
     3→ * Supports: Google, GitHub, Naver
     4→ */
     5→
     6→export interface OAuthProvider {
     7→  name: string;
     8→  clientID: string;
     9→  clientSecret: string;
    10→  callbackURL: string;
    11→}
    12→
    13→export interface OAuthConfig {
    14→  google: OAuthProvider;
    15→  github: OAuthProvider;
    16→  naver: OAuthProvider;
    17→}
    18→
    19→export const loadOAuthConfig = (): OAuthConfig => {
    20→  const baseURL = process.env.BASE_URL || 'https://253.dclub.kr';
    21→
    22→  return {
    23→    google: {
    24→      name: 'google',
    25→      clientID: process.env.GOOGLE_CLIENT_ID || '',
    26→      clientSecret: process.env.GOOGLE_CLIENT_SECRET || '',
    27→      callbackURL: `${baseURL}/auth/google/callback`,
    28→    },
    29→    github: {
    30→      name: 'github',
    31→      clientID: process.env.GITHUB_CLIENT_ID || '',
    32→      clientSecret: process.env.GITHUB_CLIENT_SECRET || '',
    33→      callbackURL: `${baseURL}/auth/github/callback`,
    34→    },
    35→    naver: {
    36→      name: 'naver',
    37→      clientID: process.env.NAVER_CLIENT_ID || '',
    38→      clientSecret: process.env.NAVER_CLIENT_SECRET || '',
    39→      callbackURL: `${baseURL}/auth/naver/callback`,
    40→    },
    41→  };
    42→};
    43→
    44→export const validateOAuthConfig = (config: OAuthConfig): void => {
    45→  const missingProviders = [];
    46→
    47→  if (!config.google.clientID) missingProviders.push('Google');
    48→  if (!config.github.clientID) missingProviders.push('GitHub');
    49→  if (!config.naver.clientID) missingProviders.push('Naver');
    50→
    51→  if (missingProviders.length > 0) {
    52→    console.warn(
    53→      `⚠️  Missing OAuth credentials for: ${missingProviders.join(', ')}`
    54→    );
    55→  }
    56→};
