     2→ * OAuth Integration Tests
     3→ */
     4→
     5→import { oauthHandler, OAuthUser } from '../oauth-handler';
     6→import { loadOAuthConfig, validateOAuthConfig } from '../oauth-config';
     7→
     8→describe('OAuth Handler', () => {
     9→  // Mock user data
    10→  const mockUser: OAuthUser = {
    11→    id: '12345',
    12→    email: 'test@example.com',
    13→    name: 'Test User',
    14→    avatar: 'https://example.com/avatar.jpg',
    15→    provider: 'google',
    16→  };
    17→
    18→  describe('Token Generation & Verification', () => {
    19→    it('should generate valid JWT token', () => {
    20→      const token = oauthHandler.generateToken(mockUser);
    21→
    22→      expect(token).toBeDefined();
    23→      expect(typeof token).toBe('string');
    24→      expect(token.split('.').length).toBe(3); // JWT has 3 parts
    25→    });
    26→
    27→    it('should verify valid token', () => {
    28→      const token = oauthHandler.generateToken(mockUser);
    29→      const verified = oauthHandler.verifyToken(token);
    30→
    31→      expect(verified).toBeDefined();
    32→      expect(verified.id).toBe(mockUser.id);
    33→      expect(verified.email).toBe(mockUser.email);
    34→      expect(verified.provider).toBe(mockUser.provider);
    35→    });
    36→
    37→    it('should return null for invalid token', () => {
    38→      const verified = oauthHandler.verifyToken('invalid.token.here');
    39→
    40→      expect(verified).toBeNull();
    41→    });
    42→
    43→    it('should reject expired token', (done) => {
    44→      process.env.JWT_SECRET = 'test-secret';
    45→
    46→      // Create token that expires immediately
    47→      const expiredToken = require('jsonwebtoken').sign(
    48→        { id: '123', email: 'test@example.com' },
    49→        'test-secret',
    50→        { expiresIn: '-1s' } // Already expired
    51→      );
    52→
    53→      const verified = oauthHandler.verifyToken(expiredToken);
    54→      expect(verified).toBeNull();
    55→
    56→      done();
    57→    });
    58→  });
    59→
    60→  describe('OAuth Config', () => {
    61→    it('should load OAuth config', () => {
    62→      const config = loadOAuthConfig();
    63→
    64→      expect(config).toHaveProperty('google');
    65→      expect(config).toHaveProperty('github');
    66→      expect(config).toHaveProperty('naver');
    67→    });
    68→
    69→    it('should validate OAuth config', () => {
    70→      const config = loadOAuthConfig();
    71→
    72→      expect(() => validateOAuthConfig(config)).not.toThrow();
    73→    });
    74→
    75→    it('should set correct callback URLs', () => {
    76→      process.env.BASE_URL = 'https://example.com';
    77→      const config = loadOAuthConfig();
    78→
    79→      expect(config.google.callbackURL).toContain('google/callback');
    80→      expect(config.github.callbackURL).toContain('github/callback');
    81→      expect(config.naver.callbackURL).toContain('naver/callback');
    82→    });
    83→  });
    84→
    85→  describe('User Data Handling', () => {
    86→    it('should preserve user data in token', () => {
    87→      const testUser: OAuthUser = {
    88→        id: 'user-123',
    89→        email: 'user@example.com',
    90→        name: 'John Doe',
    91→        avatar: 'https://example.com/john.jpg',
    92→        provider: 'github',
    93→      };
    94→
    95→      const token = oauthHandler.generateToken(testUser);
    96→      const verified = oauthHandler.verifyToken(token);
    97→
